import json
from taf.internal.aliasing import aliasing_scope
from taf.hw.hp.redfish.facade import RedfishConnection


class redfish(object):
    """
        Usage example:
            >>> from taf.hw.hp.redfish import redfish
            >>> redfish_object = redfish()
            >>> redfish_object.connect_to(host='10.16.115.4', username='aic5g', password='KhvG9y7SovPb+olf')
            >>> redfish_object.get_product_model()
            >>> redfish_object.disconnect()
    """
    ROBOT_LIBRARY_SCOPE = "TEST SUITE"
    lookup_handler, store = aliasing_scope('RedfishConnection', RedfishConnection, name=__name__)

    def connect_to(self, host, username, password, port='443', redfish_version='dl110g11_bmc', alias=None):
        """
        Provides connection and authorization to HP iLO.

        :param str host: IP address to proper iLO, eg. '10.16.115.4'.
        :param str username: Username to authenticate to HP iLO.
        :param str password: Password to authenticate to HP iLO.
        :param str redfish_version: (Optional) Specifies version of the redfish.
        :param str alias: (Optional) Name of returned connection. It not provided, this connection becomes default.
        :return: None
        """
        redfish_connection = RedfishConnection(host, username, password, port, redfish_version, alias)
        self.store.add(redfish_connection, alias)
        return redfish_connection

    @lookup_handler.implicit_lookup
    def get_system_info(self, RedfishConnection=None, query_parameters='', check_status=None):
        """
        Get system info.
        :param RedfishConnection: RedfishConnection object or string name alias if used
        :param str query_parameters: (Optional) query parameters, Please refer to redfish specification.
                     e.g. $expand, $filter, $select and so on.
        :param bool check_status: (Optional) check status flag. Support True or False.
                          if not provided, global default value is True.
        :return: system info dict.

        """
        return RedfishConnection.get_system_info(check_status, query_parameters=query_parameters)

